		for _, retention := range []RetentionPolicy{LimitsPolicy, InterestPolicy, WorkQueuePolicy} {
			t.Run(fmt.Sprintf("R%d/%s", replicas, retention), func(t *testing.T) {
				test(t, replicas, retention)
			})
		}
	}
}

